<template>
 <section class="qxc-page" aria-labelledby="qxc-title"><header class="qxc-hero"><div><span>QGAUSS / TOOLS THAT GROW WITH YOU</span><h1 id="qxc-title">整理工具箱，<em>打开新可能。</em></h1><p>把喜欢的扩展放进工作台，让创作拥有更多小帮手。</p></div><div class="qxc-cubes" aria-hidden="true"><i></i><i></i><b>✳</b></div></header>
  <div class="qxc-overview"><article><span>工具箱里的扩展</span><b>{{ visibleItems.length }}</b><small>按当前列表展示</small></article><article><span>已开放对话请求</span><b>{{ state.items.filter(item=>!item.archived&&item.enabled&&item.chatEnabled).length }}</b><small>每次请求都由使用者确认</small></article><article><span>你的创作入口</span><router-link to="/extend">打开扩展工作台 <ClientIcon name="arrowUpRight"/></router-link><small>从实际使用者的视角看看</small></article></div>
  <p v-if="state.notice" class="qxc-notice" role="status">{{ state.notice }}</p><p v-if="state.error" class="qxc-error" role="alert">{{ state.error }}</p>
  <section v-if="state.pending" class="qxc-pending" aria-label="扩展操作结果核对"><div><QLoader v-if="state.saving" :size="23"/><b>{{ state.saving?'正在保存本次操作…':'这次操作，还需要核对。' }}</b><p>先核对原操作的结果，再继续修改。重复核对不会新建扩展。</p></div><button type="button" :disabled="state.saving||state.loading" @click="reconcile">核对保存结果</button><button type="button" :disabled="state.saving||state.loading" @click="sendPending">重试原操作</button></section>
  <header class="qxc-toolbar"><div role="tablist" aria-label="扩展配置范围"><button type="button" role="tab" :aria-selected="!state.archived" @click="state.archived=false">工具箱</button><button type="button" role="tab" :aria-selected="state.archived" @click="state.archived=true">回收站</button></div><div><button type="button" class="qxc-secondary" :disabled="state.loading||state.saving" @click="load">重新读取</button><button type="button" class="qxc-primary" :disabled="!!state.pending||state.loading" @click="create">添加新扩展 <ClientIcon name="plus"/></button></div></header>
  <div v-if="state.loading" class="qxc-loading" role="status"><QLoader :size="30"/>正在整理工具箱…</div><div v-else class="qxc-grid"><article v-for="item in visibleItems" :key="item.id" class="qxc-card" :data-tone="item.tone"><header><span class="qxc-icon"><ClientIcon :name="item.icon"/></span><span class="qxc-badge">{{ item.archived?'已收起':item.enabled?'工作台可见':'暂未展示' }}</span></header><span class="qxc-kicker">{{ item.builtin?'QGAUSS ORIGINAL':'YOUR EXTENSION' }}</span><h2>{{ item.title }}</h2><p>{{ item.description||'给这个扩展补上一句介绍，让使用者更容易找到它。' }}</p><div class="qxc-card-meta"><span>{{ item.roles==='ADMIN'?'仅管理员可见':'成员与管理员可见' }}</span><span>{{ item.chatEnabled?'可请求对话':'工具体验' }}</span></div><footer><button v-if="!item.archived" type="button" :disabled="!!state.pending" @click="edit(item)">调整设定 <ClientIcon name="arrowUpRight"/></button><button v-if="item.archived" type="button" :disabled="!!state.pending" @click="mutate(item,'restore')">放回工具箱</button><button v-else type="button" class="qxc-quiet" :disabled="!!state.pending" @click="mutate(item,'archive')">移入回收站</button></footer></article><div v-if="!visibleItems.length" class="qxc-empty"><span>✳</span><h2>{{ state.archived?'收起的工具，会留在这里。':'工具箱，还可以继续长大。' }}</h2><p>{{ state.archived?'恢复后会沿用原来的设定。':'添加一个喜欢的扩展，从新的画布开始。' }}</p></div></div>
  <dialog ref="dialog" class="qxc-dialog" aria-labelledby="qxc-form-title" @cancel.prevent="close"><form v-if="state.form" @submit.prevent="save"><header><div><span>MAKE ROOM FOR SOMETHING USEFUL</span><h2 id="qxc-form-title">{{ state.form.expectedVersion?'给工具，调一点新设定。':'把新工具，放进来。' }}</h2></div><button type="button" class="qxc-close" aria-label="关闭扩展编辑" :disabled="!!state.pending" @click="close"><ClientIcon name="close"/></button></header><fieldset :disabled="!!state.pending"><div class="qxc-form-grid"><label>扩展名称<input v-model="state.form.title" required maxlength="40" placeholder="给这个工具起个名字"/></label><label>排列顺序<input v-model.number="state.form.sort" type="number" min="-1000" max="1000" required/></label><label class="wide">一句介绍<textarea v-model="state.form.description" maxlength="240" rows="2" placeholder="它能为使用者带来什么？"></textarea></label><label class="wide">扩展页面地址<input v-model="state.form.entryUrl" required maxlength="2000" :readonly="state.form.id==='qgauss-idea-canvas'" placeholder="https://你的扩展域名/页面"/><small>{{ state.form.id==='qgauss-idea-canvas'?'内置画布由 QGauss 提供，可调整展示和对话权限。':'请使用独立域名的 HTTPS 页面，地址里无需填写登录凭据。' }}</small></label><label>图标<select v-model="state.form.icon"><option value="apps">工具箱</option><option value="mindmap">灵感结构</option><option value="chat">对话</option><option value="image">画面</option><option value="palette">调色</option><option value="agent">搭档</option></select></label><label>卡片颜色<select v-model="state.form.tone"><option value="violet">柔雾紫</option><option value="lime">青柠绿</option><option value="peach">蜜桃粉</option><option value="sky">晴空蓝</option></select></label><label>谁可以打开<select v-model="state.form.roles"><option value="USER,ADMIN">成员与管理员</option><option value="ADMIN">仅管理员</option></select></label><label>对话搭档<select v-model="state.form.modelId"><option value="">使用站点默认模型</option><option v-for="model in state.models" :key="model.id" :value="model.id">{{ model.name }}</option></select></label></div><div class="qxc-switches"><label><input v-model="state.form.enabled" type="checkbox"/><span><b>在工作台展示</b><small>开启后，允许范围内的成员就能打开。</small></span></label><label><input v-model="state.form.chatEnabled" type="checkbox"/><span><b>允许请求创作搭档</b><small>使用者确认本次问题与次数后，才开始生成。</small></span></label><label v-if="state.form.id!=='qgauss-idea-canvas'"><input v-model="state.form.legacyBridge" type="checkbox"/><span><b>兼容基础消息格式</b><small>用于已有扩展的主题与对话消息；登录凭据始终留在 QGauss。</small></span></label></div></fieldset><p class="qxc-form-note">扩展停用或移入回收站后，将停止新的打开和请求。已接受的对话仍保留在记录中。</p><p v-if="state.formError" class="qxc-error" role="alert">{{ state.formError }}</p><div v-if="state.pending" class="qxc-dialog-pending"><p>保存结果尚未确认，当前内容已保留。</p><button type="button" :disabled="state.saving" @click="reconcile">核对原操作</button><button type="button" :disabled="state.saving" @click="sendPending">重试原操作</button></div><footer><button type="button" class="qxc-secondary" :disabled="!!state.pending" @click="close">放下这份草稿</button><button type="submit" class="qxc-primary" :disabled="!!state.pending">保存到工具箱 <ClientIcon name="arrowUpRight"/></button></footer></form></dialog>
 </section>
</template>
<script setup>
import {computed,nextTick,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue';
import {api} from '../../api/client.js';
import {useAuth} from '../../stores/auth.js';
import {saveExtensionAdminIntent,readExtensionAdminIntent,clearExtensionAdminIntent} from '../../lib/extension-admin-intent.js';
import ClientIcon from '../../components/reference/ClientIcon.vue';
import QLoader from '../../components/QLoader.vue';
import '../../components/design/extension-control.css';
const auth=useAuth(),dialog=ref(null),state=reactive({loading:false,saving:false,items:[],models:[],error:'',notice:'',form:null,formError:'',pending:null,archived:false}),visibleItems=computed(()=>state.items.filter(row=>!!row.archived===state.archived));
let alive=true,owner=auth.user?.id,identity=auth.identityRevision,revision=0,controller,writeController;
const current=()=>alive&&auth.isAdmin&&auth.user?.id===owner&&auth.identityRevision===identity;
async function load(){controller?.abort();const own=++revision;controller=new AbortController();state.loading=true;state.error='';try{const data=await api.get('/extensions/admin',{signal:controller.signal,retry:false});if(!current()||own!==revision)return;if(!Array.isArray(data.items)||!Array.isArray(data.models))throw Error('配置列表暂时不完整。');state.items=data.items;state.models=data.models;}catch(error){if(current()&&own===revision&&error.name!=='AbortError')state.error=error.message||'暂时无法读取工具箱。';}finally{if(current()&&own===revision)state.loading=false;}}
async function show(form){if(state.pending)return;state.form=form;state.formError='';await nextTick();if(typeof dialog.value?.showModal==='function')dialog.value.showModal();else dialog.value?.setAttribute('open','');}
function create(){void show({id:crypto.randomUUID(),expectedVersion:0,title:'',description:'',entryUrl:'',icon:'apps',tone:'violet',sort:0,enabled:false,roles:'USER,ADMIN',chatEnabled:false,legacyBridge:false,modelId:''});}
function edit(row){void show({id:row.id,expectedVersion:row.version,title:row.title,description:row.description,entryUrl:row.entryUrl,icon:row.icon,tone:row.tone,sort:row.sort,enabled:row.enabled,roles:row.roles,chatEnabled:row.chatEnabled,legacyBridge:row.legacyBridge,modelId:row.modelId||''});}
function close(){if(state.pending)return;dialog.value?.close?.();dialog.value?.removeAttribute('open');state.form=null;state.formError='';}
function pending(input){try{state.pending=reactive(saveExtensionAdminIntent(owner,input));state.error=state.formError='';void sendPending();}catch(error){state.formError=state.error=error.message;}}
function save(){if(!state.form||state.pending)return;const {id,expectedVersion,...fields}=state.form;pending({id,action:'save',body:{...fields,title:fields.title.trim(),description:fields.description.trim(),entryUrl:fields.entryUrl.trim(),modelId:fields.modelId||null,requestKey:crypto.randomUUID(),expectedVersion}});}
function mutate(row,action){if(state.pending)return;pending({id:row.id,action,body:{expectedVersion:row.version,requestKey:crypto.randomUUID()}});}
function resolved(message){clearExtensionAdminIntent(owner);state.pending=null;state.notice=message;close();}
async function sendPending(){const intent=state.pending;if(!intent||state.saving||!current())return;state.saving=true;writeController?.abort();writeController=new AbortController();try{const path='/extensions/admin/'+intent.id,result=intent.action==='save'?await api.put(path,intent.body,{signal:writeController.signal,retry:false}):await api.post(path+'/'+intent.action,intent.body,{signal:writeController.signal,retry:false});if(!current()||state.pending!==intent)return;if(result?.id!==intent.id||result.lastRequestKey!==intent.body.requestKey||!Number.isInteger(result.version))throw Error('保存结果暂时没有完整回执。');resolved(intent.action==='archive'?'扩展已收起，随时可以从回收站放回。':intent.action==='restore'?'扩展已经放回工具箱。':'扩展设定已保存。');await load();}catch(error){if(current()&&state.pending===intent){if(error.status&&error.status<500){clearExtensionAdminIntent(owner);state.pending=null;const message=error.message;await load();if(current())state.error=state.formError=message;}else state.error=state.formError='操作结果尚未确认，请先核对原操作。';}}finally{if(current())state.saving=false;}}
async function reconcile(){const intent=state.pending;if(!intent||state.saving)return;await load();if(!current()||state.pending!==intent||state.error)return;const row=state.items.find(item=>item.id===intent.id);if(row?.lastRequestKey===intent.body.requestKey)resolved('原操作已经保存，当前列表已更新。');else if(row&&row.version>intent.body.expectedVersion){resolved('扩展设定已经有更新，请以当前列表为准。');}else state.error=state.formError='暂未确认原操作是否保存，可以稍后核对，或重试同一份操作。';}
function dispose(){revision++;controller?.abort();writeController?.abort();dialog.value?.close?.();state.items=[];state.models=[];state.form=state.pending=null;state.error=state.formError=state.notice='';state.loading=state.saving=false;}
watch([()=>auth.user?.id,()=>auth.identityRevision,()=>auth.user?.role],async()=>{dispose();owner=auth.user?.id;identity=auth.identityRevision;if(current()){state.pending=readExtensionAdminIntent(owner);await load();if(state.pending)await reconcile();}});
onMounted(async()=>{state.pending=readExtensionAdminIntent(owner);await load();if(state.pending)await reconcile();});
onBeforeUnmount(()=>{alive=false;dispose();});
</script>
